import json
from datetime import date
from pathlib import Path

import requests

BASE_URL = "https://api.socbench.example"
EQUIPMENT_IDS = ["equipment-001", "equipment-002"]
SITE_ID = "site-001"
MONTH = date.today().strftime("%Y-%m")
TIMEOUT = 30

# Set these to the calibration values and alert limits appropriate for your site.
CALIBRATION = {
    "site_id": SITE_ID,
    "calibration_date": date.today().isoformat(),
    "sensors": [
        {"sensor_id": "sensor-001", "offset": 0.0, "scale_factor": 1.0},
        {"sensor_id": "sensor-002", "offset": 0.0, "scale_factor": 1.0},
    ],
}
ALERT_LIMITS = {
    "high_energy_usage_kwh": 1000.0,
    "high_demand_kw": 500.0,
}

session = requests.Session()
session.headers.update({"Accept": "application/json", "Content-Type": "application/json"})


def get_json(path, params=None):
    response = session.get(
        f"{BASE_URL}{path}", params=params, timeout=TIMEOUT
    )
    response.raise_for_status()
    return response.json()


def post_json(path, payload):
    response = session.post(
        f"{BASE_URL}{path}", json=payload, timeout=TIMEOUT
    )
    response.raise_for_status()
    return response.json()


def put_json(path, payload):
    response = session.put(
        f"{BASE_URL}{path}", json=payload, timeout=TIMEOUT
    )
    response.raise_for_status()
    return response.json()


# Calibrate sensors before collecting data.
calibration_result = put_json("/sensors/calibration", CALIBRATION)

# Retrieve historical energy use and patterns for the monthly performance report
# and demand forecast.
energy_usage = get_json(
    "/energy-usage",
    {"site_id": SITE_ID, "equipment_ids": EQUIPMENT_IDS, "period": MONTH},
)
energy_patterns = get_json(
    "/energy-patterns",
    {"site_id": SITE_ID, "equipment_ids": EQUIPMENT_IDS, "period": MONTH},
)
electricity_demand = get_json(
    "/electricity-demand",
    {"site_id": SITE_ID, "period": MONTH},
)
forecast = get_json(
    "/forecast-usage",
    {"site_id": SITE_ID, "equipment_ids": EQUIPMENT_IDS, "period": MONTH},
)

# Collect current readings and equipment monitoring/status details.
real_time_data = get_json(
    "/real-time-data",
    {"site_id": SITE_ID, "equipment_ids": EQUIPMENT_IDS},
)
equipment_monitoring = get_json(
    "/equipment-monitoring",
    {"site_id": SITE_ID, "equipment_ids": EQUIPMENT_IDS},
)
equipment_status = get_json(
    "/equipment-status",
    {"site_id": SITE_ID, "equipment_ids": EQUIPMENT_IDS},
)

# Upload the collected readings to enhance smart-meter monitoring.
smart_meter_upload = post_json(
    "/smart-meters/data",
    {
        "site_id": SITE_ID,
        "timestamp": date.today().isoformat(),
        "readings": real_time_data,
    },
)

# Request an efficiency assessment for the selected equipment.
efficiency_check = post_json(
    "/equipment-efficiency-check",
    {
        "site_id": SITE_ID,
        "equipment_ids": EQUIPMENT_IDS,
        "period": MONTH,
        "energy_usage": energy_usage,
        "energy_patterns": energy_patterns,
    },
)


def find_threshold_alerts(value, path="$"):
    """Apply local alert limits when the API does not expose an alert endpoint."""
    alerts = []

    if isinstance(value, dict):
        for key, child in value.items():
            key_lower = str(key).lower()
            child_path = f"{path}.{key}"
            if isinstance(child, (int, float)) and not isinstance(child, bool):
                if (
                    "kwh" in key_lower or "energy" in key_lower
                ) and child > ALERT_LIMITS["high_energy_usage_kwh"]:
                    alerts.append(
                        {
                            "path": child_path,
                            "value": child,
                            "limit": ALERT_LIMITS["high_energy_usage_kwh"],
                            "scenario": "high_energy_usage",
                        }
                    )
                elif (
                    "kw" in key_lower or "demand" in key_lower
                ) and child > ALERT_LIMITS["high_demand_kw"]:
                    alerts.append(
                        {
                            "path": child_path,
                            "value": child,
                            "limit": ALERT_LIMITS["high_demand_kw"],
                            "scenario": "high_demand",
                        }
                    )
            else:
                alerts.extend(find_threshold_alerts(child, child_path))
    elif isinstance(value, list):
        for index, child in enumerate(value):
            alerts.extend(find_threshold_alerts(child, f"{path}[{index}]"))

    return alerts


monthly_report = {
    "site_id": SITE_ID,
    "month": MONTH,
    "equipment_ids": EQUIPMENT_IDS,
    "calibration": calibration_result,
    "energy_usage": energy_usage,
    "energy_patterns": energy_patterns,
    "electricity_demand": electricity_demand,
    "forecast": forecast,
    "real_time_data": real_time_data,
    "equipment_monitoring": equipment_monitoring,
    "equipment_status": equipment_status,
    "smart_meter_upload": smart_meter_upload,
    "efficiency_check": efficiency_check,
    "alert_limits": ALERT_LIMITS,
    "alerts": find_threshold_alerts(
        {
            "energy_usage": energy_usage,
            "electricity_demand": electricity_demand,
            "real_time_data": real_time_data,
        }
    ),
}

Path(f"energy_performance_{MONTH}.json").write_text(
    json.dumps(monthly_report, indent=2, default=str),
    encoding="utf-8",
)

