import json
from urllib.parse import quote

import requests

BASE_URL = "https://api.socbench.example"
TIMEOUT = 30


def get_json(path):
    response = requests.get(f"{BASE_URL}{path}", timeout=TIMEOUT)
    response.raise_for_status()
    return response.json()


def post_json(path, payload):
    response = requests.post(
        f"{BASE_URL}{path}",
        json=payload,
        timeout=TIMEOUT,
    )
    response.raise_for_status()
    return response.json()


def put_json(path, payload):
    response = requests.put(
        f"{BASE_URL}{path}",
        json=payload,
        timeout=TIMEOUT,
    )
    response.raise_for_status()
    return response.json()


def records(data):
    if isinstance(data, list):
        return data
    if isinstance(data, dict):
        for key in ("data", "items", "results", "records", "schedules", "equipment"):
            value = data.get(key)
            if isinstance(value, list):
                return value
    return []


maintenance_schedule = get_json("/maintenance-schedule")
equipment_status = get_json("/equipment-status")
equipment_monitoring = get_json("/equipment-monitoring")
energy_usage = get_json("/energy-usage")
forecast_usage = get_json("/forecast-usage")
generation_forecast = get_json("/generation/forecast")

usage_details = {
    "energy_usage": energy_usage,
    "equipment_monitoring": equipment_monitoring,
    "forecast_usage": forecast_usage,
    "generation_forecast": generation_forecast,
}

efficiency_analysis = post_json(
    "/equipment-efficiency-check",
    {
        "equipment_status": equipment_status,
        "usage_details": usage_details,
        "scope": "all_facilities",
    },
)

maintenance_plan = {
    "scope": "all_facilities",
    "current_schedule": maintenance_schedule,
    "equipment_status": equipment_status,
    "equipment_monitoring": equipment_monitoring,
    "efficiency_analysis": efficiency_analysis,
    "usage_details": usage_details,
    "planning_request": (
        "Evaluate equipment condition and efficiency, prioritize maintenance "
        "by risk and operational impact, and propose schedule improvements."
    ),
}

resource_maintenance_result = put_json(
    "/resources/maintenance",
    maintenance_plan,
)

schedule_updates = []
for item in records(maintenance_schedule):
    if not isinstance(item, dict):
        continue

    schedule_id = item.get("id")
    if schedule_id is None:
        continue

    update_payload = {
        "current_schedule": item,
        "equipment_status": equipment_status,
        "equipment_monitoring": equipment_monitoring,
        "efficiency_analysis": efficiency_analysis,
        "usage_details": usage_details,
        "planning_request": (
            "Review this facility's maintenance schedule and update it based on "
            "equipment condition, usage, efficiency, and forecast information."
        ),
    }
    updated = put_json(
        f"/maintenance-schedule/{quote(str(schedule_id), safe='')}",
        update_payload,
    )
    schedule_updates.append(updated)

generated_report = post_json(
    "/recommendation-report",
    {
        "maintenance_plan": maintenance_plan,
        "resource_maintenance_result": resource_maintenance_result,
        "schedule_updates": schedule_updates,
        "report_request": (
            "Generate a maintenance report covering all facilities, equipment "
            "efficiency, supporting usage data, priorities, and planned actions."
        ),
    },
)

report_feedback = post_json(
    "/recommendation-report",
    {
        "report": generated_report,
        "source_data": {
            "maintenance_schedule": maintenance_schedule,
            "equipment_status": equipment_status,
            "equipment_monitoring": equipment_monitoring,
            "energy_usage": energy_usage,
            "forecast_usage": forecast_usage,
            "generation_forecast": generation_forecast,
            "efficiency_analysis": efficiency_analysis,
        },
        "feedback_request": (
            "Assess the report's accuracy against the supplied source data. "
            "Identify unsupported or inconsistent statements, note missing "
            "facility or equipment coverage, and suggest specific improvements."
        ),
    },
)

print(
    json.dumps(
        {
            "efficiency_analysis": efficiency_analysis,
            "resource_maintenance_result": resource_maintenance_result,
            "schedule_updates": schedule_updates,
            "maintenance_report": generated_report,
            "report_accuracy_feedback": report_feedback,
        },
        indent=2,
        default=str,
    )
)

