        classification.get("classification", classification)
        if isinstance(classification, dict)
        else classification
    )
    classification_text = str(classification_data).lower()
    requires_compliance = (
        isinstance(classification_data, dict)
        and any(
            classification_data.get(key)
            for key in ("requires_compliance_check", "compliance_required", "requires_compliance")
        )
    ) or "compliance required" in classification_text

