import os
import requests

BASE_URL = "https://api.socbench.example"
session = requests.Session()
session.headers.update({"Accept": "application/json"})
if os.getenv("SOCBENCH_API_TOKEN"):
    session.headers["Authorization"] = f"Bearer {os.environ['SOCBENCH_API_TOKEN']}"


def request_json(method, path, **kwargs):
    response = session.request(method, f"{BASE_URL}{path}", timeout=30, **kwargs)
    response.raise_for_status()
    if response.content:
        return response.json()
    return {}


def rows_from(payload):
    if isinstance(payload, list):
        return payload
    if isinstance(payload, dict):
        for key in ("products", "items", "inventory", "metrics", "data", "results"):
            value = payload.get(key)
            if isinstance(value, list):
                return value
            if isinstance(value, dict):
                nested = rows_from(value)
                if nested:
                    return nested
    return []


def product_id(row):
    return row.get("product_id", row.get("id"))


def performance_score(row):
    for key in ("performance_score", "performance", "sales", "units_sold", "score"):
        value = row.get(key)
        if isinstance(value, (int, float)):
            return value
    return None


def find_non_performer(rows):
    candidates = [
        row for row in rows
        if product_id(row) is not None and performance_score(row) is not None
    ]
    if not candidates:
        return None
    return min(candidates, key=performance_score)


# Capture baseline product, waste, and operational performance data.
product_metrics_before = request_json("GET", "/product/metrics")
waste_before = request_json("GET", "/waste/reports")
performance_before = request_json("GET", "/performance/metrics")

product_rows = rows_from(product_metrics_before)
non_performer = find_non_performer(product_rows)
non_performing_id = os.getenv("NON_PERFORMING_PRODUCT_ID")
if non_performing_id is None and non_performer:
    non_performing_id = product_id(non_performer)

# Update the configured sustainable product, or choose a sustainable product
# returned by the metrics endpoint.
sustainable_id = os.getenv("SUSTAINABLE_PRODUCT_ID")
if sustainable_id is None:
    sustainable_row = next(
        (
            row for row in product_rows
            if row.get("sustainable") is True
            or row.get("is_sustainable") is True
            or row.get("ecological_attributes")
        ),
        next((row for row in product_rows if product_id(row) != non_performing_id), None),
    )
    if sustainable_row:
        sustainable_id = product_id(sustainable_row)

updated_product = None
if sustainable_id is not None:
    updated_product = request_json(
        "PUT",
        "/product/update",
        json={
            "product_id": sustainable_id,
            "sustainable": True,
            "ecological_attributes": {
                "recyclable_packaging": True,
                "renewable_materials": True,
                "reduced_carbon_emissions": True,
                "reduced_water_usage": True,
            },
        },
    )

# Remove the identified non-performing product.
removed_product = None
if non_performing_id is not None:
    removed_product = request_json(
        "DELETE", f"/product/{non_performing_id}"
    )

# Inspect inventory and remove entries explicitly marked obsolete, expired,
# excess, or above their stated maximum stock.
inventory_before = request_json("GET", "/inventory/status")
inventory_rows = rows_from(inventory_before)
items_to_remove = []

for item in inventory_rows:
    item_id = item.get("inventory_id", item.get("item_id", item.get("id")))
    if item_id is None:
        continue

    status = str(item.get("status", "")).lower()
    obsolete = (
        item.get("obsolete") is True
        or item.get("expired") is True
        or status in {"obsolete", "expired", "excess"}
    )
    quantity = item.get("quantity", item.get("stock_quantity"))
    maximum = item.get("max_stock", item.get("maximum_stock"))
    excess = (
        isinstance(quantity, (int, float))
        and isinstance(maximum, (int, float))
        and quantity > maximum
    )
    if obsolete or excess:
        items_to_remove.append(item_id)

removed_inventory = []
for item_id in items_to_remove:
    removed_inventory.append(
        request_json(
            "DELETE",
            "/inventory/remove",
            json={"inventory_id": item_id},
        )
    )

# Recheck operational and ecological indicators after the changes.
performance_after = request_json("GET", "/performance/metrics")
product_metrics_after = request_json("GET", "/product/metrics")
waste_after = request_json("GET", "/waste/reports")
inventory_after = request_json("GET", "/inventory/status")

# Use available inventory records to obtain category values. The food-category
# list is limited to categories whose names or item types indicate food.
category_values = set()
food_category_values = set()
for item in rows_from(inventory_after):
    category = item.get("category", item.get("category_name"))
    item_type = str(item.get("type", item.get("item_type", ""))).lower()
    if category:
        category_values.add(str(category))
        if "food" in str(category).lower() or item_type == "food":
            food_category_values.add(str(category))

# Forecast demand using the available historical product metrics and inventory.
sustainable_product_ids = [
    product_id(row)
    for row in rows_from(product_metrics_after)
    if product_id(row) is not None
    and (
        row.get("sustainable") is True
        or row.get("is_sustainable") is True
        or row.get("ecological_attributes")
        or str(product_id(row)) == str(sustainable_id)
    )
]
forecast = request_json(
    "POST",
    "/analytics/forecast",
    json={
        "product_ids": sustainable_product_ids,
        "historical_data": product_metrics_after,
        "inventory_data": inventory_after,
    },
)

result = {
    "non_performing_product_id": non_performing_id,
    "removed_product": removed_product,
    "updated_sustainable_product": updated_product,
    "removed_inventory_ids": items_to_remove,
    "removed_inventory_results": removed_inventory,
    "performance_before": performance_before,
    "performance_after": performance_after,
    "product_metrics_before": product_metrics_before,
    "product_metrics_after": product_metrics_after,
    "waste_reports_before": waste_before,
    "waste_reports_after": waste_after,
    "available_categories": sorted(category_values),
    "available_food_categories": sorted(food_category_values),
    "sustainable_product_demand_forecast": forecast,
}
print(result)

