import json
import os
from urllib.parse import quote

import requests

BASE_URL = "https://api.socbench.example"
TIMEOUT = 30
session = requests.Session()
session.headers.update({"Accept": "application/json"})
if os.getenv("API_TOKEN"):
    session.headers["Authorization"] = f"Bearer {os.environ['API_TOKEN']}"


def api_get(path, **kwargs):
    response = session.get(f"{BASE_URL}{path}", timeout=TIMEOUT, **kwargs)
    response.raise_for_status()
    return response.json()


def api_put(path, payload):
    response = session.put(
        f"{BASE_URL}{path}",
        json=payload,
        timeout=TIMEOUT,
    )
    response.raise_for_status()
    return response.json() if response.content else None


def records(data):
    if isinstance(data, list):
        return data
    if isinstance(data, dict):
        for key in ("results", "items", "data", "alerts", "policies", "readings", "claims"):
            if isinstance(data.get(key), list):
                return data[key]
    return []


def patient_id_from(item):
    return item.get("patient_id") or item.get("patientId")


alerts = records(api_get("/alerts", params={"status": "active"}))
policies = records(api_get("/policies"))
claims = records(api_get("/claims"))

report = {
    "active_alerts": [],
    "claims_retrieved": len(claims),
    "limitations": [
        "No documented endpoint is available to update insurance claims.",
        "No documented endpoint or request schema is available to dismiss alerts.",
        "No documented endpoint is available to inspect system configuration.",
    ],
}

for alert in alerts:
    patient_id = patient_id_from(alert)
    if patient_id is None:
        report["active_alerts"].append(
            {"alert": alert, "error": "Alert has no patient_id; patient records were not retrieved."}
        )
        continue

    patient_key = quote(str(patient_id), safe="")
    readings = api_get(f"/readings/{patient_key}")
    history = api_get(f"/patients/{patient_key}/history")

    matching_policies = [
        policy
        for policy in policies
        if str(policy.get("patient_id", policy.get("patientId", ""))) == str(patient_id)
    ]

    findings = {
        "alert": alert,
        "readings": readings,
        "existing_medical_history": history,
        "matching_policies": matching_policies,
    }

    # Record the retrieved findings through the documented patient update endpoint.
    # The API documentation does not specify the accepted patient-update schema.
    try:
        api_put(
            f"/patients/{patient_key}",
            {"medical_history_findings": findings},
        )
        findings["patient_update"] = "submitted"
    except requests.HTTPError as exc:
        findings["patient_update"] = f"failed: {exc}"

    report["active_alerts"].append(
        {
            "patient_id": patient_id,
            "findings": findings,
            "coverage_policy_candidates": matching_policies,
        }
    )

print(json.dumps(report, indent=2, default=str))

