import requests
from datetime import datetime, timedelta

BASE_URL = "https://api.socbench.example"


def _as_datetime(value):
    if not value:
        return None
    try:
        return datetime.fromisoformat(value.replace("Z", "+00:00"))
    except (AttributeError, TypeError, ValueError):
        return None


def _items(response_data):
    if isinstance(response_data, list):
        return response_data
    if isinstance(response_data, dict):
        for key in ("consultations", "scheduled_consultations", "records", "history"):
            value = response_data.get(key)
            if isinstance(value, list):
                return value
    return []


def organize_virtual_consultation(
    patient_id,
    provider_id,
    proposed_start,
    duration_minutes=30,
    session=None,
):
    http = session or requests.Session()

    scheduled_response = http.get(
        f"{BASE_URL}/patients/{patient_id}/scheduled-consultations",
        timeout=30,
    )
    scheduled_response.raise_for_status()
    scheduled_data = scheduled_response.json()
    scheduled = _items(scheduled_data)

    start = _as_datetime(proposed_start)
    if start is None:
        raise ValueError("proposed_start must be an ISO 8601 datetime string")
    end = start + timedelta(minutes=duration_minutes)

    for consultation in scheduled:
        existing_start = _as_datetime(
            consultation.get("start_time")
            or consultation.get("starts_at")
            or consultation.get("scheduled_at")
        )
        existing_end = _as_datetime(
            consultation.get("end_time") or consultation.get("ends_at")
        )
        if existing_start and existing_end and start < existing_end and end > existing_start:
            raise ValueError("The proposed time conflicts with a scheduled consultation")

    history_response = http.get(
        f"{BASE_URL}/patients/{patient_id}/history",
        timeout=30,
    )
    history_response.raise_for_status()
    history_data = history_response.json()
    history_records = _items(history_data)

    tools_response = http.get(f"{BASE_URL}/consultation-tools", timeout=30)
    tools_response.raise_for_status()
    consultation_tools = tools_response.json()

    claims = []
    if isinstance(history_data, dict):
        claims = history_data.get("insurance_claims", [])

    activity_overview = {
        "scheduled_consultation_count": len(scheduled),
        "medical_history_record_count": len(history_records),
        "consultation_tools": consultation_tools,
        "medical_history": history_data,
    }

    payload = {
        "patient_id": patient_id,
        "provider_id": provider_id,
        "scheduled_at": proposed_start,
        "duration_minutes": duration_minutes,
        "medical_history": history_data,
        "activity_overview": activity_overview,
    }

    consultation_response = http.post(
        f"{BASE_URL}/virtual-consultations",
        json=payload,
        timeout=30,
    )
    consultation_response.raise_for_status()

    return {
        "scheduled_consultations": scheduled_data,
        "medical_history": history_data,
        "consultation_tools": consultation_tools,
        "consultation": consultation_response.json(),
        "insurance_claims_found_in_history": claims,
        "unsupported_actions": [
            "No documented endpoint is available to retrieve or update insurance claims.",
            "No documented endpoint is available to dismiss alerts.",
        ],
    }

