import requests

BASE_URL = "https://api.socbench.example"
session = requests.Session()
session.headers.update({"Accept": "application/json", "Content-Type": "application/json"})


def get_list(path, *list_keys):
    response = session.get(f"{BASE_URL}{path}", timeout=30)
    response.raise_for_status()
    data = response.json()
    if isinstance(data, list):
        return data
    if isinstance(data, dict):
        for key in list_keys:
            if isinstance(data.get(key), list):
                return data[key]
    return []


patients = get_list("/patients", "patients", "results")
inventory = get_list("/inventory", "inventory", "items", "results")
alerts = get_list("/alerts", "alerts", "results")


def normalize(value):
    return str(value).strip().casefold() if value is not None else ""


def item_key(item):
    return normalize(
        item.get("item_id")
        or item.get("supply_id")
        or item.get("id")
        or item.get("name")
        or item.get("item_name")
        or item.get("supply_name")
    )


def item_name(item):
    return (
        item.get("name")
        or item.get("item_name")
        or item.get("supply_name")
        or item.get("item_id")
        or item.get("supply_id")
        or item.get("id")
    )


inventory_by_key = {item_key(item): item for item in inventory if item_key(item)}
patient_demand = {}

for patient in patients:
    supplies = (
        patient.get("required_supplies")
        or patient.get("supplies_needed")
        or patient.get("medical_supplies")
        or patient.get("supplies")
        or []
    )
    if isinstance(supplies, (str, dict)):
        supplies = [supplies]

    for supply in supplies:
        if isinstance(supply, str):
            key, quantity = normalize(supply), 1
        elif isinstance(supply, dict):
            key = normalize(
                supply.get("item_id")
                or supply.get("supply_id")
                or supply.get("id")
                or supply.get("name")
                or supply.get("item_name")
                or supply.get("supply_name")
            )
            quantity = supply.get("quantity", supply.get("needed_quantity", 1))
        else:
            continue

        if key:
            try:
                quantity = max(1, int(quantity))
            except (TypeError, ValueError):
                quantity = 1
            patient_demand[key] = patient_demand.get(key, 0) + quantity

active_alerts = []
alert_keys = set()
for alert in alerts:
    status = normalize(alert.get("status"))
    is_active = alert.get("active") is True or status in {
        "active", "open", "unresolved", "pending"
    }
    if is_active:
        active_alerts.append(alert)
        key = item_key(alert)
        if key:
            alert_keys.add(key)

restock_plan = []
for key, required_quantity in patient_demand.items():
    item = inventory_by_key.get(key)
    if not item:
        continue

    current_quantity = (
        item.get("quantity")
        if item.get("quantity") is not None
        else item.get("stock_quantity", item.get("stock", 0))
    )
    try:
        current_quantity = int(current_quantity)
    except (TypeError, ValueError):
        current_quantity = 0

    if current_quantity < required_quantity or key in alert_keys:
        restock_plan.append(
            {
                "item": item,
                "key": key,
                "current": current_quantity,
                "target": max(current_quantity, required_quantity),
                "alerted": key in alert_keys,
            }
        )

restock_plan.sort(key=lambda entry: (not entry["alerted"], entry["current"]))

for entry in restock_plan:
    item = entry["item"]
    item_id = (
        item.get("item_id")
        or item.get("supply_id")
        or item.get("id")
        or item_name(item)
    )
    response = session.post(
        f"{BASE_URL}/inventory/update",
        json={"item_id": item_id, "quantity": entry["target"]},
        timeout=30,
    )
    response.raise_for_status()

