import json
import os
from datetime import datetime, timezone
from pathlib import Path
from urllib.parse import quote

import requests

BASE_URL = "https://api.socbench.example"
REPORT_PATH = Path("compliance_report.json")

session = requests.Session()
token = os.getenv("SOCBENCH_API_TOKEN")
if token:
    session.headers["Authorization"] = f"Bearer {token}"
session.headers["Accept"] = "application/json"


def api(method, path, **kwargs):
    response = session.request(method, f"{BASE_URL}{path}", timeout=30, **kwargs)
    response.raise_for_status()
    if response.status_code == 204 or not response.content:
        return None
    return response.json()


def records(value, key):
    if isinstance(value, list):
        return value
    if isinstance(value, dict):
        result = value.get(key, [])
        return result if isinstance(result, list) else []
    return []


def threat_id(threat):
    return threat.get("id") or threat.get("threat_id")


def vulnerabilities(threat):
    result = []
    for field in ("software_vulnerabilities", "vulnerabilities", "cves"):
        value = threat.get(field, [])
        if isinstance(value, list):
            result.extend(value)
        elif value:
            result.append(value)

    software = threat.get("software", [])
    if isinstance(software, list):
        for item in software:
            if isinstance(item, dict):
                for field in ("software_vulnerabilities", "vulnerabilities", "cves"):
                    value = item.get(field, [])
                    if isinstance(value, list):
                        result.extend(value)
                    elif value:
                        result.append(value)

    # Deduplicate while preserving the original values and order.
    unique = []
    seen = set()
    for item in result:
        marker = json.dumps(item, sort_keys=True, default=str)
        if marker not in seen:
            seen.add(marker)
            unique.append(item)
    return unique


def referenced_threat_ids(alert):
    values = []
    single = alert.get("threat_id")
    if single is not None:
        values.append(str(single))
    many = alert.get("threat_ids", [])
    if isinstance(many, list):
        values.extend(str(value) for value in many)
    return set(values)


def main():
    # Trigger the configured hook, then fetch the threats and alerts it should address.
    api("POST", "/trigger-hook", json={})
    threat_data = api("GET", "/threats")
    alert_data = api("GET", "/alerts")
    threats = records(threat_data, "threats")
    alerts = records(alert_data, "alerts")

    active_threat_ids = {
        str(identifier)
        for threat in threats
        if (identifier := threat_id(threat)) is not None
    }

    threat_by_id = {
        str(identifier): threat
        for threat in threats
        if (identifier := threat_id(threat)) is not None
    }

    updated_alerts = []
    deleted_alerts = []
    associated_vulnerabilities = {}

    for threat_identifier, threat in threat_by_id.items():
        associated_vulnerabilities[threat_identifier] = vulnerabilities(threat)

    for alert in alerts:
        alert_identifier = alert.get("id") or alert.get("alert_id")
        if alert_identifier is None:
            continue

        linked_ids = referenced_threat_ids(alert)

        # Remove only alerts explicitly linked to threats that are no longer listed.
        if linked_ids and linked_ids.isdisjoint(active_threat_ids):
            api("DELETE", f"/alerts/{quote(str(alert_identifier), safe='')}")
            deleted_alerts.append(str(alert_identifier))
            continue

        linked_threats = linked_ids & active_threat_ids
        if not linked_threats:
            continue

        vuln_list = []
        for identifier in sorted(linked_threats):
            vuln_list.extend(associated_vulnerabilities.get(identifier, []))

        # Preserve the existing alert fields and refresh its vulnerability associations.
        if alert.get("software_vulnerabilities") != vuln_list:
            updated_alert = dict(alert)
            updated_alert["software_vulnerabilities"] = vuln_list
            api(
                "PUT",
                f"/alerts/{quote(str(alert_identifier), safe='')}",
                json=updated_alert,
            )
            updated_alerts.append(str(alert_identifier))

    # No compliance-report endpoint or regulatory criteria are documented. Save a
    # local evidence summary without claiming that regulatory compliance was assessed.
    report = {
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "compliance_assessment": "not_assessed",
        "assessment_note": (
            "The documented API provides no compliance-report endpoint or regulatory "
            "criteria. This file summarizes the retrieved threats and alert changes only."
        ),
        "threat_count": len(threats),
        "threats": [
            {
                "threat_id": threat_id(threat),
                "software_vulnerabilities": vulnerabilities(threat),
            }
            for threat in threats
        ],
        "updated_alert_ids": updated_alerts,
        "deleted_alert_ids": deleted_alerts,
    }
    REPORT_PATH.write_text(json.dumps(report, indent=2, default=str), encoding="utf-8")


if __name__ == "__main__":
    main()

