import copy
import re
import requests

BASE_URL = "https://api.socbench.example"
session = requests.Session()
session.headers.update({"Accept": "application/json"})


def get_json(path):
    response = session.get(f"{BASE_URL}{path}", timeout=30)
    response.raise_for_status()
    return response.json()


def as_records(data, *keys):
    if isinstance(data, list):
        return data
    if isinstance(data, dict):
        for key in keys:
            value = data.get(key)
            if isinstance(value, list):
                return value
    return []


equipment_data = get_json("/equipment")
equipment = as_records(equipment_data, "equipment", "items", "results")

threat_data = get_json("/threats")
threats = as_records(threat_data, "threats", "items", "results")

systems_data = get_json("/systems")
systems = as_records(systems_data, "systems", "items", "results")

tracking_data = get_json("/tracking/assets")
tracked_assets = as_records(tracking_data, "assets", "items", "results")

compliance_data = get_json("/compliance/reports")
compliance_reports = as_records(
    compliance_data, "reports", "items", "results"
)


def normalize(value):
    return re.sub(r"[^a-z0-9]+", " ", str(value).lower()).strip()


def software_entries(item):
    for key in ("installed_software", "software", "applications"):
        value = item.get(key)
        if isinstance(value, list):
            return key, value
    return None, None


def software_name(entry):
    if isinstance(entry, str):
        return entry
    if isinstance(entry, dict):
        for key in ("name", "product", "software", "package"):
            if entry.get(key):
                return str(entry[key])
    return ""


def threat_software_names(threat):
    names = []
    for key in (
        "affected_software",
        "vulnerable_software",
        "software",
        "affected_products",
        "products",
    ):
        value = threat.get(key)
        if isinstance(value, str):
            names.append(value)
        elif isinstance(value, list):
            for item in value:
                name = software_name(item)
                if name:
                    names.append(name)
    return names


def explicit_patch_version(threat):
    for key in (
        "patched_version",
        "patch_version",
        "fixed_version",
        "recommended_version",
        "update_version",
    ):
        value = threat.get(key)
        if isinstance(value, str) and value.strip():
            return value.strip()
    remediation = threat.get("remediation")
    if isinstance(remediation, dict):
        for key in ("patched_version", "fixed_version", "version"):
            value = remediation.get(key)
            if isinstance(value, str) and value.strip():
                return value.strip()
    return None


def equipment_may_be_affected(item, threat):
    item_id = str(item.get("id", ""))
    affected_ids = threat.get("affected_equipment_ids") or threat.get(
        "affected_asset_ids"
    )
    if isinstance(affected_ids, list) and item_id in {
        str(value) for value in affected_ids
    }:
        return True

    names = [normalize(name) for name in threat_software_names(threat)]
    _, installed = software_entries(item)
    installed_names = [normalize(software_name(entry)) for entry in installed or []]

    return any(
        affected and any(affected in installed_name or installed_name in affected
                         for installed_name in installed_names if installed_name)
        for affected in names
    )


equipment_updates = []
potentially_affected = []

for item in equipment:
    if not isinstance(item, dict) or item.get("id") is None:
        continue

    matching_threats = [
        threat
        for threat in threats
        if isinstance(threat, dict) and equipment_may_be_affected(item, threat)
    ]
    if matching_threats:
        potentially_affected.append(
            {"equipment_id": item["id"], "threats": matching_threats}
        )

    software_key, installed = software_entries(item)
    if not installed:
        continue

    updated_item = copy.deepcopy(item)
    updated_software = copy.deepcopy(installed)
    changed = False

    for threat in matching_threats:
        patch_version = explicit_patch_version(threat)
        if not patch_version:
            continue

        affected_names = [
            normalize(name) for name in threat_software_names(threat)
        ]
        for index, entry in enumerate(updated_software):
            name = normalize(software_name(entry))
            if not name or not any(
                affected in name or name in affected
                for affected in affected_names
                if affected
            ):
                continue

            if isinstance(entry, dict):
                version_key = next(
                    (
                        key
                        for key in ("version", "installed_version")
                        if key in entry
                    ),
                    "version",
                )
                if entry.get(version_key) != patch_version:
                    entry[version_key] = patch_version
                    updated_software[index] = entry
                    changed = True
            elif isinstance(entry, str):
                updated_software[index] = f"{entry} ({patch_version})"
                changed = True

    if changed:
        updated_item[software_key] = updated_software
        response = session.put(
            f"{BASE_URL}/equipment/{item['id']}",
            json=updated_item,
            timeout=30,
        )
        response.raise_for_status()
        equipment_updates.append(item["id"])

updated_equipment = []
for item in equipment:
    if isinstance(item, dict) and item.get("id") is not None:
        updated_equipment.append(
            get_json(f"/equipment/{item['id']}")
        )

# Compare the installed software with system software references where present.
software_by_equipment = {}
for item in updated_equipment:
    if not isinstance(item, dict):
        continue
    key, entries = software_entries(item)
    if key:
        software_by_equipment[str(item.get("id"))] = [
            software_name(entry) for entry in entries
        ]

system_software_references = [
    system
    for system in systems
    if isinstance(system, dict)
    and any(
        key in system
        for key in ("software", "installed_software", "supported_software")
    )
]

# The documented API provides no cloud compatibility or scaling operation;
# retain the retrieved system and tracking data for assessment.
results = {
    "potentially_affected_equipment": potentially_affected,
    "equipment_updated": equipment_updates,
    "updated_equipment": updated_equipment,
    "software_by_equipment": software_by_equipment,
    "systems": systems,
    "system_software_references": system_software_references,
    "tracked_assets": tracked_assets,
    "compliance_reports": compliance_reports,
}

