import os
import requests

BASE_URL = "https://api.socbench.example"
TIMEOUT = 30

# Replace these with the regions and billing template to review.
REGIONS = ["region-1", "region-2"]
BILLING_TEMPLATE_ID = "billing-template-1"

session = requests.Session()
api_key = os.getenv("SOCBENCH_API_KEY")
if api_key:
    session.headers["Authorization"] = f"Bearer {api_key}"
session.headers["Accept"] = "application/json"


def api_request(method, path, **kwargs):
    response = session.request(
        method,
        f"{BASE_URL}{path}",
        timeout=TIMEOUT,
        **kwargs,
    )
    response.raise_for_status()
    if response.content:
        return response.json()
    return {}


def records(value):
    """Yield dictionary records from nested API responses."""
    if isinstance(value, dict):
        yield value
        for child in value.values():
            yield from records(child)
    elif isinstance(value, list):
        for child in value:
            yield from records(child)


# Gather current demand, forecasts, regional status, and efficiency data.
demand = api_request(
    "GET", "/realtime-demand", params={"regions": ",".join(REGIONS)}
)
forecasts = api_request(
    "GET", "/forecast-patterns", params={"regions": ",".join(REGIONS)}
)
zones_status = api_request(
    "GET", "/zones-status", params={"regions": ",".join(REGIONS)}
)
efficiency_reports = api_request(
    "GET", "/efficiency-reports", params={"regions": ",".join(REGIONS)}
)

# Review the requested billing-template configuration using the documented
# configuration endpoint.
billing_configuration = api_request(
    "PUT",
    "/regions/config",
    json={
        "billing_template_id": BILLING_TEMPLATE_ID,
        "action": "review",
        "dry_run": True,
    },
)

# Identify critical regions from the returned zone status.
critical_markers = {"critical", "emergency", "high", "high-priority"}
critical_regions = []
for record in records(zones_status):
    status = str(
        record.get("status", record.get("priority", record.get("severity", "")))
    ).strip().lower()
    region = (
        record.get("region_id")
        or record.get("region")
        or record.get("zone_id")
        or record.get("zone")
    )
    if region and status in critical_markers and region in REGIONS:
        if region not in critical_regions:
            critical_regions.append(region)

# Adjust the distribution strategy using the gathered demand and forecast data.
distribution_adjustment = api_request(
    "PUT",
    "/adjust-distribution",
    json={
        "regions": REGIONS,
        "real_time_demand": demand,
        "forecast_patterns": forecasts,
        "efficiency_reports": efficiency_reports,
    },
)

# Create actionable recommendations for critical regions.
recommendations = [
    {
        "region": region,
        "priority": "high",
        "actions": [
            "Shift flexible loads away from forecast peak-demand periods.",
            "Review controllable loads and reduce nonessential consumption during peaks.",
            "Check distribution loading and rebalance supply where operationally feasible.",
        ],
        "evidence": {
            "real_time_demand": demand,
            "forecast_patterns": forecasts,
            "efficiency_reports": efficiency_reports,
        },
    }
    for region in critical_regions
]

# Notify repair teams about the high-priority recommendations.
if recommendations:
    incident_notification = api_request(
        "POST",
        "/incident-response",
        json={
            "priority": "high",
            "notification_type": "energy_saving_recommendations",
            "regions": critical_regions,
            "recommendations": recommendations,
            "notify_repair_teams": True,
        },
    )
else:
    incident_notification = {}

# Find inactive distribution points in the status response and remove them
# from monitoring through the documented distribution-manipulation endpoint.
inactive_point_ids = []
for record in records(zones_status):
    status = str(record.get("status", "")).strip().lower()
    point_id = (
        record.get("distribution_point_id")
        or record.get("distributionPointId")
        or record.get("point_id")
    )
    if point_id and status in {"inactive", "disabled", "offline"}:
        if point_id not in inactive_point_ids:
            inactive_point_ids.append(point_id)

if inactive_point_ids:
    removal_result = api_request(
        "POST",
        "/distribution/manipulate",
        json={
            "action": "remove",
            "distribution_point_ids": inactive_point_ids,
            "remove_from_monitoring": True,
        },
    )
else:
    removal_result = {}

results = {
    "demand": demand,
    "forecasts": forecasts,
    "zones_status": zones_status,
    "efficiency_reports": efficiency_reports,
    "billing_configuration_review": billing_configuration,
    "distribution_adjustment": distribution_adjustment,
    "critical_regions": critical_regions,
