import requests

BASE_URL = "https://api.socbench.example"
TIMEOUT = 30

session = requests.Session()
session.headers.update({"Accept": "application/json", "Content-Type": "application/json"})


def get_json(path):
    response = session.get(f"{BASE_URL}{path}", timeout=TIMEOUT)
    response.raise_for_status()
    return response.json()


def post_json(path, payload):
    response = session.post(f"{BASE_URL}{path}", json=payload, timeout=TIMEOUT)
    response.raise_for_status()
    return response.json()


def send_json(method, path, payload=None):
    response = session.request(
        method, f"{BASE_URL}{path}", json=payload, timeout=TIMEOUT
    )
    response.raise_for_status()
    return response.json() if response.content else {}


def find_records(value):
    if isinstance(value, list):
        return [item for item in value if isinstance(item, dict)]
    if isinstance(value, dict):
        for key in ("zones", "data", "results", "records", "demand", "status"):
            nested = value.get(key)
            if isinstance(nested, list):
                return [item for item in nested if isinstance(item, dict)]
            if isinstance(nested, dict):
                records = find_records(nested)
                if records:
                    return records
        return [value]
    return []


def number_from(record, keys):
    for key in keys:
        value = record.get(key)
        if isinstance(value, (int, float)) and not isinstance(value, bool):
            return float(value)
    return None


def zone_name(record, fallback):
    for key in ("zone_id", "zone", "zone_name", "name", "id"):
        if record.get(key) is not None:
            return record[key]
    return fallback


# Clear manual settings first so subsequent actions use automated controls.
override_reset = send_json("DELETE", "/override-settings")

demand_data = get_json("/realtime-demand")
zones_data = get_json("/zones-status")
forecast_data = get_json("/forecast-patterns")
efficiency_data = get_json("/efficiency-reports")
renewables_data = get_json("/renewables-status")

demand_records = find_records(demand_data)
zones_records = find_records(zones_data)

demand_keys = (
    "electricity_demand",
    "current_demand",
    "demand",
    "load",
    "consumption",
    "usage",
)
zone_demands = []
for index, record in enumerate(demand_records):
    demand = number_from(record, demand_keys)
    if demand is not None:
        zone_demands.append(
            {
                "zone": zone_name(record, index),
                "demand": demand,
                "source": record,
            }
        )

values = sorted(item["demand"] for item in zone_demands)
if values:
    mean_demand = sum(values) / len(values)
    percentile_index = min(len(values) - 1, int(0.75 * len(values)))
    high_demand_cutoff = max(mean_demand, values[percentile_index])
    high_demand_zones = [
        item for item in zone_demands if item["demand"] >= high_demand_cutoff
    ]
    alert_threshold = mean_demand * 1.25
else:
    mean_demand = None
    high_demand_cutoff = None
    high_demand_zones = []
    alert_threshold = None

high_zone_names = [item["zone"] for item in high_demand_zones]

# Allocate resources toward zones currently experiencing the greatest demand.
allocation_result = post_json(
    "/allocate-resources",
    {
        "strategy": "prioritize_high_demand_zones",
        "high_demand_zones": high_zone_names,
        "demand_data": demand_data,
        "zones_status": zones_data,
        "renewables_status": renewables_data,
    },
)

# Adjust distribution using current demand, forecasts, and renewable availability.
distribution_result = send_json(
    "PUT",
    "/adjust-distribution",
    {
        "strategy": "demand_and_renewables_optimized",
        "high_demand_zones": high_zone_names,
        "demand_data": demand_data,
        "forecast_data": forecast_data,
        "renewables_status": renewables_data,
    },
)

# Configure an alert for demand surges relative to the observed average.
threshold_result = {}
if alert_threshold is not None:
    threshold_result = send_json(
        "PATCH",
        "/update-thresholds",
        {
            "demand_surge": {
                "enabled": True,
                "threshold": alert_threshold,
                "comparison": "greater_than",
                "baseline_demand": mean_demand,
                "multiplier": 1.25,
            }
        },
    )

# Produce targeted suggestions from the observed demand and available insights.
suggestions = []
for item in high_demand_zones:
    suggestions.append(
        {
            "zone": item["zone"],
            "suggestion": (
                "Shift flexible loads to off-peak periods and prioritize "
                "renewable or lower-emission supply."
            ),
            "observed_demand": item["demand"],
        }
    )

if not high_demand_zones:
    suggestions.append(
        {
            "suggestion": (
                "Review the efficiency report and forecast for equipment or "
                "scheduling opportunities to reduce consumption."
            )
        }
    )

results = {
    "override_reset": override_reset,
    "realtime_demand": demand_data,
    "zones_status": zones_data,
    "forecast_patterns": forecast_data,
    "efficiency_reports": efficiency_data,
    "renewables_status": renewables_data,
    "high_demand_zones": high_demand_zones,
    "high_demand_cutoff": high_demand_cutoff,
    "allocation": allocation_result,
    "distribution_adjustment": distribution_result,
    "alert_threshold_update": threshold_result,
    "energy_saving_suggestions": suggestions,
}

