import requests

BASE_URL = "https://api.socbench.example"
session = requests.Session()


def get_json(path, params):
    response = session.get(
        f"{BASE_URL}{path}",
        params=params,
        timeout=30,
    )
    response.raise_for_status()
    return response.json()


# Retrieve New York City property valuation data for feature analysis.
valuation_data = get_json(
    "/properties/valuation",
    {"city": "New York City", "state": "NY"},
)


def analyze_features(data):
    counts = Counter()
    feature_fields = {
        "property_type", "bedrooms", "bathrooms", "stories", "year_built",
        "parking", "garage", "has_garage", "pool", "has_pool",
        "heating", "cooling", "lot_size", "square_feet", "sqft",
        "condition", "amenities",
    }

    def add_feature(value):
        if isinstance(value, (str, int, float, bool)):
            counts[str(value)] += 1
        elif isinstance(value, list):
            for item in value:
                add_feature(item)
        elif isinstance(value, dict):
            for key, item in value.items():
                if isinstance(item, (str, int, float, bool)):
                    counts[f"{key}: {item}"] += 1
                else:
                    add_feature(item)

    def walk(value):
        if isinstance(value, dict):
            for key, item in value.items():
                normalized_key = key.lower().replace("-", "_").replace(" ", "_")
                if normalized_key in {"features", "common_features", "property_features"}:
                    add_feature(item)
                elif normalized_key in feature_fields:
                    add_feature(item)
                walk(item)
        elif isinstance(value, list):
            for item in value:
                walk(item)

    walk(data)
    return counts.most_common(10)


common_features = analyze_features(valuation_data)

